 40→type ActionButtonProps = ComponentProps<typeof Button>;
 41→/**
 42→ * A customized version of the `<Button/>` component specifically meant to be used for banner actions.
 43→ */
 44→const ActionButton = (props: ActionButtonProps) => {
 45→  return (
 46→    <Button trimmed
 47→      {...props}
 48→      className={cx(cl['bk-banner__action'], cl['bk-banner__action--button'], props.className)}
 49→      // Prevent clicks from triggering any click handlers on the Banner itself (e.g. to prevent toast dismissal)
 50→      onClick={event => { event.stopPropagation(); props.onClick?.(event); }}
 51→    />
 52→  );
 53→};
