 22→interface ReactTableOptions<D extends object> extends ReactTable.TableOptions<D> {
 23→  // Add custom properties here
 24→  //onClick?: (row: ReactTable.Row<D>) => void,
 25→}
 26→
 27→export type TableProviderEagerProps<D extends object> = {
 28→  children: React.ReactNode,
 29→  columns: ReactTableOptions<D>['columns'],
 30→  items: ReactTableOptions<D>['data'],
 31→  getRowId: ReactTableOptions<D>['getRowId'],
 32→  isRowSelectDisabled?: ReactTable.TableInstance<D>['isRowSelectDisabled'],
 33→  plugins?: Array<ReactTable.PluginHook<D>>,
 34→  stickyColumns?: ReactTable.TableInstance<D>['bkStickyColumns'],
 35→  initialState?: Partial<ReactTable.TableState<D>>,
 36→  isReady?: boolean,
 37→};
 38→export const TableProviderEager = <D extends object>(props: TableProviderEagerProps<D>) => {
 39→  const {
 40→    children,
 41→    columns,
 42→    stickyColumns,
 43→    items,
 44→    getRowId,
 45→    isRowSelectDisabled,
 46→    plugins = [],
 47→    initialState = {},
 48→    isReady = true,
 49→  } = props;
 50→  
 51→  const tableOptions: ReactTable.TableOptions<D> = {
 52→    columns,
 53→    data: items,
 54→    ...(getRowId && { getRowId }),
 55→    ...(stickyColumns ? { bkStickyColumns: stickyColumns } : {}),
 56→    ...(isRowSelectDisabled ? { isRowSelectDisabled } : {}),
 57→  };
 58→
 59→  const table = ReactTable.useTable(
 60→    {
 61→      ...tableOptions,
 62→      defaultColumn: {
 63→        disableGlobalFilter: true,
 64→        disableSortBy: true,
 65→      },
 66→      
 67→      initialState: {
 68→        // useSortBy
 69→        sortBy: [{ id: 'name', desc: false }],
 70→        
 71→        // useGlobalFilter
 72→        globalFilter: '',
 73→        
 74→        // useFilters
 75→        filters: [],
 76→        
 77→        // usePagination
 78→        pageSize: 10,
 79→        pageIndex: 0,
 80→        
 81→        ...initialState,
 82→      },
 83→      
 84→      // useGlobalFilter
 85→      manualGlobalFilter: false,
 86→      
 87→      // useSortBy
 88→      disableSortRemove: true,
 89→      
 90→      // usePagination
 91→      manualPagination: false,
 92→      autoResetPage: false, // Do not automatically reset to first page if the data changes
 93→    },
 94→    ReactTable.useGlobalFilter,
 95→    ReactTable.useFilters,
 96→    ReactTable.useSortBy,
 97→    ReactTable.usePagination,
 98→    ReactTable.useRowSelect,
 99→    ...plugins,
100→  );
101→  
102→  // Note: the `table` reference is mutated, so cannot use it as dependency for `useMemo` directly
103→  // biome-ignore lint/correctness/useExhaustiveDependencies: (See above.)
104→  const context = React.useMemo<TableContextState<D>>(() => ({
105→    status: { ready: isReady, loading: false, error: null },
106→    setStatus() {},
107→    reload() {},
108→    table,
109→  }), [table.state, ...Object.values(tableOptions)]);
110→  
111→  const TableContext = React.useMemo(() => createTableContext<D>(), []);
112→  
113→  return (
114→    <TableContext value={context}>
115→      {children}
116→    </TableContext>
117→  );
118→};
119→TableProviderEager.displayName = 'TableProviderEager';
