148→export type DataTableEagerProps = Omit<React.ComponentProps<typeof DataTableSync>, 'table' | 'status'> & {
149→  children?: React.ReactNode,
150→  className?: ClassNameArgument,
151→  footer?: React.ReactNode,
152→};
153→export const DataTableEager = ({ children, className, footer, ...propsRest }: DataTableEagerProps) => {
154→  const { table, status } = useTable();
155→  
156→  React.useEffect(() => {
157→    if (table.page.length === 0 && table.state.pageIndex > 0 && table.canPreviousPage) {
158→      // Edge case: no items and yet we are not on the first page. Navigate back to the previous page.
159→      table.previousPage();
160→    }
161→  }, [table.page.length, table.state.pageIndex, table.canPreviousPage, table.previousPage]);
162→  
163→  // Use `<Pagination/>` by default, unless the table is empty (in which case there are "zero" pages)
164→  const footerDefault = status.ready && table.rows.length > 0 ? <Pagination/> : null;
165→  const footerWithFallback = typeof footer === 'undefined' ? footerDefault : footer;
166→  
167→  return (
168→    <DataTableSync
169→      footer={footerWithFallback}
170→      {...propsRest}
171→      className={cx(
172→        cl['bk-data-table-eager'],
173→        { [cl['bk-data-table-eager--loading']]: !status.ready },
174→        className,
175→      )}
176→      table={table}
177→      status={status}
178→    >
179→      {children}
180→    </DataTableSync>
181→  );
182→};
183→DataTableEager.displayName = 'DataTableEager';
